import React from "react";
export const findContent = (children, targetComponent, id) => {
    let found = null;
    React.Children.forEach(children, (child) => {
        if (found || !React.isValidElement(child)) {
            return;
        }
        if (id ? child.type === targetComponent && child.props.id === id : child.type === targetComponent) {
            found = child;
            return;
        }
        if (child.props.children) {
            found = findContent(child.props.children, targetComponent, id);
        }
    });
    return found;
};
